"""Printed 302: partial limit definitions and examples 2–4 opening."""
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
BLOCKS=[paragraph('The partial derivative ∂f(x,y)/∂y with respect to y is obtained by keeping y variable and x constant.'),heading('11.1.3 Partial derivatives of a function of two variables'),paragraph('If z=f(x,y) is a function of two variables, its first partial derivatives with respect to x and y are fₓ and fᵧ, respectively, defined by:'),eq(r'\frac{∂}{∂x}f(x,y)=f_x=\lim_{\Delta x\to0}\frac{f(x+\Delta x,y)-f(x,y)}{\Delta x}','i'),eq(r'\frac{∂}{∂y}f(x,y)=f_y=\lim_{\Delta y\to0}\frac{f(x,y+\Delta y)-f(x,y)}{\Delta y}','ii'),paragraph('Provided the limits exist.'),heading('Example 2'),paragraph('If f(x,y)=x³y+xy², find partial derivatives fₓ and fᵧ.'),heading('Solution'),paragraph('The partial derivatives w.r.t. x and y are:'),eq(r'\frac{∂f}{∂x}=f_x=\frac{∂}{∂x}(x^3y+xy^2)=3x^2y+y^2,\quad y\ \mathrm{constant}'),eq(r'\frac{∂f}{∂y}=f_y=\frac{∂}{∂y}(x^3y+xy^2)=x^3+2xy,\quad x\ \mathrm{constant}'),heading('Example 3'),paragraph('The function is z=x² sin(3x+y³). Find zₓ and zᵧ at (π/3,0).'),heading('Solution'),paragraph('With y constant, use the product and chain rules:'),eq(r'z_x=\frac{∂}{∂x}\left[x^2\sin(3x+y^3)\right]'),eq(r'z_x=2x\sin(3x+y^3)+x^2\cos(3x+y^3)\frac{∂}{∂x}(3x+y^3)'),eq(r'z_x=2x\sin(3x+y^3)+x^2\cos(3x+y^3)(3+0)=2x\sin(3x+y^3)+3x^2\cos(3x+y^3)'),eq(r'z_x(\pi/3,0)=\frac{2\pi}{3}\sin\left(\frac{3\pi}{3}+0\right)+\frac{3\pi^2}{9}\cos\left(\frac{3\pi}{3}+0\right)=\frac{2\pi}{3}\sin\pi+\frac{3\pi^2}{9}\cos\pi=-\frac{\pi^2}{3}'),paragraph('With x constant, the derivative w.r.t. y is:'),eq(r'z_y=\frac{∂}{∂y}\left[x^2\sin(3x+y^3)\right]=x^2\cos(3x+y^3)\frac{∂}{∂y}(3x+y^3)'),eq(r'z_y=x^2\cos(3x+y^3)(0+3y^2)=3x^2y^2\cos(3x+y^3)'),eq(r'z_y(\pi/3,0)=3\left(\frac{\pi^2}{9}\right)(0)^2\cos\left(\frac{3\pi}{3}\right)=0'),heading('Example 4'),paragraph('Suppose the temperature of water at a point on a river where a nuclear power plant discharges hot waste water is approximated by:'),eq(r'T(x,y)=2x+5y+xy-40','i'),paragraph('x represents river-water temperature in degrees Celsius before it reaches the plant; y is the number of megawatts (in hundreds) produced by the plant. (a) Find and interpret Tₓ(9,5). (b) Find and interpret Tᵧ(9,5).'),heading('Solution'),paragraph('(a) The partial derivative of (i) w.r.t. x is the rate of change in T with respect to x:'),eq(r'T_x=2+y,\quad y\ \mathrm{constant}'),note('For each partial limit the other coordinate is fixed. A product or chain rule still applies to any dependence on the variable being differentiated. In Example 3, trigonometric derivatives and π/3 are in radians. Example 4 continues on printed 303; one y-unit represents 100 megawatts, so units must be retained in the interpretation.')]
PAGES=[page('155_page_2.jpg',302,BLOCKS)]
PAGES[0].update(title='PARTIAL DIFFERENTIATION',visualStatus='Native partial limits, full product/chain rule calculations and source temperature model',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':155,'side':'right','reason':'All partial symbols, difference quotient increments, exponents and model coefficients visually checked'})
EXAMPLES=[]
for n,q,steps,ans in [
('2','Find fₓ and fᵧ for f(x,y)=x³y+xy².',['To find fₓ, keep y constant while differentiating x.','The derivative of x³y with respect to x is 3x²y.','The derivative of xy² with respect to x is y², hence fₓ=3x²y+y².','To find fᵧ, keep x constant while differentiating y.','The derivative of x³y is x³ and that of xy² is 2xy, giving fᵧ=x³+2xy.','These polynomials are differentiable at every real pair (x,y). Applying the rules to each term verifies both derivatives.'],'fₓ=3x²y+y²; fᵧ=x³+2xy.'),
('3','For z=x²sin(3x+y³), find zₓ,zᵧ at (π/3,0).',['Keep y fixed for zₓ, and apply the product rule to x² and sin(3x+y³).','Differentiate the inner expression with respect to x: ∂(3x+y³)/∂x=3.','Thus zₓ=2x sin(3x+y³)+3x² cos(3x+y³).','Keep x fixed for zᵧ; the inner y derivative is 3y². Hence zᵧ=3x²y²cos(3x+y³).','At (π/3,0), the angle is π, so sinπ=0 and cosπ=−1.','Therefore zₓ=−3(π²/9)=−π²/3 and zᵧ=0 because of the factor y².','The source evaluation uses radians, as required by the standard trigonometric derivative formulas.'],'zₓ(π/3,0)=−π²/3; zᵧ(π/3,0)=0.')]:
 EXAMPLES.append({'num':n,'title':'Partial Product and Chain Rules','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':302,'jpg':'155_page_2.jpg','verification':'All source derivative factors and point values checked'}]})
